import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"FRP 内网穿透","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/frp.md","filePath":"deploy/frp.md","lastUpdated":1792044498000}'),e={name:"deploy/frp.md"};function p(l,s,h,r,k,d){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="frp-内网穿透" tabindex="-1">FRP 内网穿透 <a class="header-anchor" href="#frp-内网穿透" aria-label="Permalink to &quot;FRP 内网穿透&quot;">​</a></h1><p>将内网服务暴露到公网，客户端 frpc 主动连到服务端 frps。</p><p><a href="https://github.com/fatedier/frp" target="_blank" rel="noreferrer">https://github.com/fatedier/frp</a></p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>到 <a href="https://github.com/fatedier/frp/releases" target="_blank" rel="noreferrer">Releases</a> 下载对应平台的压缩包，解压即可，无需安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以 linux amd64 为例</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/fatedier/frp/releases/download/v0.61.1/frp_0.61.1_linux_amd64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -zxvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frp_0.61.1_linux_amd64.tar.gz</span></span></code></pre></div><p>解压后目录里有 <code>frps</code>（服务端）和 <code>frpc</code>（客户端）两个可执行文件，对应两份配置。</p><h2 id="服务端-frps" tabindex="-1">服务端 frps <a class="header-anchor" href="#服务端-frps" aria-label="Permalink to &quot;服务端 frps&quot;">​</a></h2><p><code>frps.toml</code>：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frps 服务监听的本机端口</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bindPort = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">55555</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frpc 客户端连接鉴权 token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth.token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your_token&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frps 服务 web 界面配置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webServer.addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webServer.port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">57001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webServer.user = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;username&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webServer.password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;adminpass&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 日志打印配置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">log.to = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/frp/logs&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">log.level = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">log.maxDays = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span></span></code></pre></div><p>启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./frps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./frps.toml</span></span></code></pre></div><h2 id="客户端-frpc" tabindex="-1">客户端 frpc <a class="header-anchor" href="#客户端-frpc" aria-label="Permalink to &quot;客户端 frpc&quot;">​</a></h2><p><code>frpc.toml</code>：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 建立连接</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">serverAddr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;server address&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">serverPort = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">55555</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth.token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your_token&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 全局配置</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transport.tls.enable = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transport.tcpMux = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transport.poolCount = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">proxies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tcp-ex&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localIP = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localPort = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">remotePort = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">57002</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transport.useCompression = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>启动：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./frpc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./frpc.toml</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>全局配置</strong>（客户端到服务端的连接）：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>transport.tls.enable = true</code></td><td>加密客户端到服务端</td></tr><tr><td><code>transport.tcpMux = true</code></td><td>开启多路复用</td></tr><tr><td><code>transport.poolCount = 3</code></td><td>提前准备工作连接</td></tr></tbody></table><p><strong>连接参数</strong>（单个代理）：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>transport.useCompression = true</code></td><td>压缩隧道内容，节省带宽</td></tr></tbody></table>`,22)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
